namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data.
        _notifications.Add(new(_nextId++, "Welcome to the app!", DateTime.UtcNow.AddMinutes(-10)));
        _notifications.Add(new(_nextId++, "Your profile was updated.", DateTime.UtcNow.AddMinutes(-5)));
        _notifications.Add(new(_nextId++, "New feature available: dark mode.", DateTime.UtcNow.AddMinutes(-1)));
    }

    /// <summary>Returns all notifications.</summary>
    public List<Notification> GetAll()
    {
        lock (_lock)
        {
            return [.. _notifications];
        }
    }

    /// <summary>Returns only notifications with an Id greater than <paramref name="sinceId"/>.</summary>
    public List<Notification> GetSince(int sinceId)
    {
        lock (_lock)
        {
            return _notifications.Where(n => n.Id > sinceId).ToList();
        }
    }

    /// <summary>Simulates an incoming notification (called on a timer internally).</summary>
    public void SimulateIncoming()
    {
        string[] messages =
        [
            "You have a new follower!",
            "Someone liked your post.",
            "Scheduled maintenance tonight.",
            "Your export is ready to download.",
            "A comment was added to your thread.",
        ];

        lock (_lock)
        {
            var msg = messages[(_nextId - 1) % messages.Length];
            _notifications.Add(new(_nextId++, msg, DateTime.UtcNow));
        }
    }
}

