@page "/notifications"
@using NotificationsApp.Services
@rendermode @(new InteractiveServerRenderMode(prerender: true))
@inject NotificationService NotificationSvc
@implements IDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill">@_notifications.Count</span>
</h1>

@if (_notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var n in _notifications.OrderByDescending(x => x.Timestamp))
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <span>@n.Message</span>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<Notification> _notifications = new();
    private CancellationTokenSource? _cts;

    // Runs during prerender AND when the component becomes interactive.
    // PersistentComponentState would also work, but tracking the max Id is
    // simpler: on the second call we just skip re-loading because we already
    // have data from the prerender pass that was serialized into the page.
    private bool _initialized;

    protected override void OnInitialized()
    {
        if (!_initialized)
        {
            _notifications = NotificationSvc.GetAll();
            _initialized = true;
        }
    }

    // OnAfterRender only fires on the interactive (WebSocket-connected) render,
    // never during static SSR — exactly the right place to start the poll loop.
    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        // Generate a fake notification server-side every ~8 s so there is
        // something new to pick up.
        _ = SimulateServerNotificationsAsync(ct);

        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), ct).ConfigureAwait(false);

            var maxId = _notifications.Count > 0 ? _notifications.Max(n => n.Id) : 0;
            var newer = NotificationSvc.GetSince(maxId);

            if (newer.Count > 0)
            {
                await InvokeAsync(() =>
                {
                    _notifications.AddRange(newer);
                    StateHasChanged();
                });
            }
        }
    }

    private async Task SimulateServerNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(8), ct).ConfigureAwait(false);
            NotificationSvc.SimulateIncoming();
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

